  const modelChoices = DEFAULT_AICHAT_MODELS.map((model) =>
    `<button type="button" role="option" data-model="${escapeHtml(model.value)}" aria-selected="${model.value === defaultModel}">${escapeHtml(model.value === defaultModel ? 'Gemma-4' : model.label)}</button>`
  ).join('');
